import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Ge.css";

function Generate() {
  const navigate = useNavigate();
  const canvasRef = useRef(null);
  const containerRef = useRef(null);
  const [isFading, setIsFading] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [timestamp, setTimestamp] = useState(new Date());

  const initializeCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return null;

    const ctx = canvas.getContext("2d");
    if (!ctx) return null;

    return { canvas, ctx };
  };

  useEffect(() => {
    const generatedImage = localStorage.getItem("generatedImage");
    if (!generatedImage) {
      console.error("No generated image found in localStorage");
      setIsLoading(false);
      return;
    }

    const canvasInit = initializeCanvas();
    if (!canvasInit) {
      console.error("Failed to initialize canvas");
      setIsLoading(false);
      return;
    }

    const { canvas, ctx } = canvasInit;
    const img = new Image();

    img.onload = () => {
      // Clear canvas and draw the base image
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      // Generate the piece-based composition
      generateImage();
      setIsLoading(false);
    };

    img.onerror = () => {
      console.error("Failed to load image");
      setIsLoading(false);
    };

    img.src = generatedImage;
    setTimestamp(new Date());

    return () => {
      localStorage.removeItem("generatedImage");
    };
  }, []);

  const generateImage = async () => {
    const canvasInit = initializeCanvas();
    if (!canvasInit) {
      console.error("Failed to initialize canvas for image generation");
      return;
    }

    const { canvas, ctx } = canvasInit;

    // Get the current image data
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

    // Calculate piece size
    const pieceSize = Math.floor(canvas.width / 30);
    const pieces = [];

    // Create pieces
    for (let y = 0; y < 30; y++) {
      for (let x = 0; x < 30; x++) {
        pieces.push({
          x: x * pieceSize,
          y: y * pieceSize,
          width: pieceSize,
          height: pieceSize
        });
      }
    }

    // Shuffle pieces
    for (let i = pieces.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pieces[i], pieces[j]] = [pieces[j], pieces[i]];
    }

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Place pieces from center
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;

    for (const piece of pieces) {
      // Random rotation
      const angle = Math.random() * Math.PI * 2;

      // Random distance from center (closer to center)
      const distance = Math.random() * 200;
      const direction = Math.random() * Math.PI * 2;

      const x = centerX + Math.cos(direction) * distance;
      const y = centerY + Math.sin(direction) * distance;

      // Random scale (0.5 to 1.5)
      const scale = 0.5 + Math.random();

      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(angle);
      ctx.scale(scale, scale);

      // Draw the piece
      ctx.drawImage(
        canvas,
        piece.x, piece.y, piece.width, piece.height,
        -piece.width/2, -piece.height/2, piece.width, piece.height
      );

      ctx.restore();
    }
  };

  const handleRegenerate = async () => {
    setIsRegenerating(true);
    setIsFading(true);
    try {
      await generateImage();
    } finally {
      setTimeout(() => {
        setIsFading(false);
        setIsRegenerating(false);
      }, 300);
    }
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  return (
    <div ref={containerRef} className="ge-container">
      <button
        onClick={() => navigate('/ho')}
        className="ge-button ge-button-back"
      >
        Go Back
      </button>

      {isLoading || isRegenerating ? (
        <div style={{ 
          position: 'absolute', 
          top: '50%', 
          left: '50%', 
          transform: 'translate(-50%, -50%)',
          color: 'white',
          fontSize: '24px',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: '10px'
        }}>
          <div>Loading...</div>
          {isRegenerating && (
            <div style={{
              width: '40px',
              height: '40px',
              border: '4px solid #f3f3f3',
              borderTop: '4px solid #3498db',
              borderRadius: '50%',
              animation: 'spin 1s linear infinite'
            }} />
          )}
        </div>
      ) : (
        <canvas
          ref={canvasRef}
          width={1080}
          height={1080}
          className="ge-canvas"
          style={{ opacity: isFading ? 0.2 : 1 }}
        />
      )}

      <div className="ge-timestamp">
        {timestamp.toLocaleString()}
      </div>

      <div className="ge-button-container">
        <button
          onClick={handleRegenerate}
          className="ge-button ge-button-regenerate"
          disabled={isRegenerating}
        >
          {isRegenerating ? 'Regenerating...' : 'Regenerate'}
        </button>
        <button
          onClick={handleDownload}
          className="ge-button ge-button-download"
          disabled={isRegenerating}
        >
          Download
        </button>
      </div>
    </div>
  );
}

export default Generate;
